#include "KS/SRC/vector3d_shared.h"
#include "KS/SRC/sphere_shared.h"
#include "g++-2/stl_list_shared.h"
#include "g++-2/stl_vector_shared.h"

class stringx {};
template<class T> struct less {};
class region;
class portal;

template<class K, class N, class E, class C = less<K> >
class graph {
public:
    class node;
    class edge {
        E data;
        node *dest;
    public:
        E &get_data() { return data; }
        node *get_dest() { return dest; }
    };
    class node : public list<edge> {
        N data;
    public:
        N &get_data() { return data; }
    };
};

typedef graph<stringx, region *, portal *> region_graph;
typedef region_graph::node region_node;
typedef region_node::iterator edge_iterator;

class ai_polypath_cell;

class region {
public:
    void visit();
    bool already_visited() const;
    void add(ai_polypath_cell *);
};

class vr_pmesh {};

class portal : public vr_pmesh {
public:
    bool touches_sphere(const sphere &) const;
    int get_max_faces() const;
};

typedef int face_ref;
bool collide_polygon_segment(
    face_ref,
    const vr_pmesh *,
    const vector3d &,
    const vector3d &,
    vector3d &
);

static vector<region_node *> cell_regions(32);

class ai_polypath_cell {
    char pad0[28];
    vector3d m_Vertex[3];
    char pad1[68];
    vector3d m_WallMidpoint[3];

    void _intersect(
        region_node *r,
        const sphere &the_sphere,
        bool use_high_res_intersect
    );
};

void ai_polypath_cell::_intersect( region_node* r, const sphere &the_sphere, bool use_high_res_intersect )
{
  // add region to list
  r->get_data()->visit();
  cell_regions.push_back( r );

  // check for intersection with portals leading from this region
  edge_iterator tei = r->begin();
  edge_iterator tei_end = r->end();
  for ( ; tei!=tei_end; ++tei )
  {
    // don't bother with regions we've already visited
    region_node* dest = (*tei).get_dest();
    if ( !dest->get_data()->already_visited() )
    {
      portal* port = (*tei).get_data();
      // don't need to recurse across inactive portals, unless you're a door or doorframe!
      // intersection of entity sphere and portal cylinder
      if ( port->touches_sphere(the_sphere) )
      {
        if ( use_high_res_intersect )
        {
          const vector3d& v0 = the_sphere.get_center();
          vector3d hit_loc;

          bool intersected = false;
          for ( int j=0; j<port->get_max_faces() && !intersected; ++j )
          {
            for ( int i=0; i<3 && !intersected; ++i )
            {
              vector3d v1 = m_Vertex[i];
              vector3d v2 = i < 2 ? m_Vertex[i+1] : m_Vertex[0];
              vector3d v3 = m_WallMidpoint[i];

              if ( collide_polygon_segment( j, port, v0, v1, hit_loc )    // center to vertex
                || collide_polygon_segment( j, port, v1, v2, hit_loc )    // side of triangle
                || collide_polygon_segment( j, port, v0, v3, hit_loc ))   // center to midpoint of side
              {
                _intersect( dest, the_sphere, use_high_res_intersect );
                intersected = true;
                break;
              }
            }
          }
        }
        else
          _intersect( dest, the_sphere, use_high_res_intersect );
      }
    }
  }
}
